<template><view class="page"><view v-if="order" class="card"><view class="row"><text>{{order.returnNo}}</text><text class="status">{{order.statusText||order.status}}</text></view><text>原调拨单：{{order.originalTransferNo}}</text><text>退回金额：{{order.returnAmount||0}}</text><text>原因：{{order.returnReason}}</text><text>退款状态：{{order.refundStatusText||order.refundStatus}}</text><text v-if="order.rejectReason" class="warn">驳回原因：{{order.rejectReason}}</text><text v-if="order.logisticsNo">退货物流：{{order.logisticsCompany||''}} {{order.logisticsNo}}</text></view><view class="card"><view class="title">退回明细</view><view v-for="x in items" :key="x.id" class="row line"><text>{{x.productName}} / {{x.skuName||'默认规格'}}</text><text>x{{x.returnQuantity}} / ¥{{x.returnAmount}}</text></view></view><view v-if="mode==='own'&&order" class="card"><button v-if="order.status==='SUBMITTED'" @click="cancel">取消申请</button><template v-if="order.status==='AUDIT_APPROVED'"><input v-model="ship.logisticsCompany" placeholder="物流公司"/><input v-model="ship.logisticsNo" placeholder="物流单号"/><button type="primary" @click="submitShip">确认已寄回</button></template></view><view v-if="mode==='handle'&&order" class="card"><button v-if="order.status==='SUBMITTED'" type="primary" @click="audit(true)">审核通过并冻结库存</button><button v-if="order.status==='SUBMITTED'" @click="audit(false)">审核驳回</button><button v-if="order.status==='RETURN_SHIPPED'" type="primary" @click="receive">确认收货并回流库存</button><template v-if="order.status==='REFUND_PENDING'"><payment-voucher-upload v-model="refundUrl"/><textarea v-model="refundRemark" placeholder="退款流水号、退款方式和备注"/><button type="primary" @click="refund">确认线下退款完成</button></template><button v-if="['SUBMITTED','AUDIT_APPROVED'].includes(order.status)" @click="close">关闭退回单</button></view><view v-if="logs.length" class="card"><view class="title">流程记录</view><view v-for="x in logs" :key="x.id" class="log"><text>{{x.auditActionText||x.auditAction}}：{{x.auditRemark||'--'}}</text><text class="muted">{{x.createTime}}</text></view></view></view></template>
<script>import paymentVoucherUpload from '@/components/jk/payment-voucher-upload.vue';import{getJkStockTransferReturnDetail,getJkHandledReturnDetail,cancelJkStockTransferReturn,shipJkStockTransferReturn,auditJkHandledReturn,receiveJkHandledReturn,refundJkHandledReturn,closeJkHandledReturn}from'@/api/jk.js';export default{components:{paymentVoucherUpload},data(){return{id:0,mode:'own',order:null,items:[],logs:[],ship:{logisticsCompany:'',logisticsNo:''},refundUrl:'',refundRemark:''}},onLoad(q){this.id=Number(q.id);this.mode=q.mode||'own';this.load()},methods:{load(){(this.mode==='handle'?getJkHandledReturnDetail:getJkStockTransferReturnDetail)(this.id).then(r=>{const p=r.data||r||{};this.order=p.returnOrder;this.items=p.items||[];this.logs=p.auditLogs||[]})},cancel(){uni.showModal({title:'取消退回申请',editable:true,success:r=>{if(r.confirm)cancelJkStockTransferReturn(this.id,{businessId:this.id,remark:r.content||'申请人取消'}).then(()=>this.load())}})},submitShip(){if(!this.ship.logisticsNo)return this.$util.Tips({title:'请输入物流单号'});shipJkStockTransferReturn(this.id,{requestNo:'RETURN-SHIP-'+Date.now(),...this.ship,remark:'申请人已寄回'}).then(()=>this.load())},audit(approved){uni.showModal({title:approved?'审核通过':'审核驳回',editable:true,placeholderText:'请输入审核备注',success:r=>{if(r.confirm)auditJkHandledReturn({businessId:this.id,approved,remark:r.content||(approved?'审核通过':'审核驳回')}).then(()=>this.load())}})},receive(){uni.showModal({title:'确认收到退货',editable:true,placeholderText:'请输入收货检查结果',success:r=>{if(r.confirm)receiveJkHandledReturn({businessId:this.id,remark:r.content||'确认收到退货'}).then(()=>this.load())}})},refund(){if(!this.refundUrl)return this.$util.Tips({title:'请上传退款凭证'});refundJkHandledReturn({returnId:this.id,requestNo:'RETURN-REFUND-'+Date.now(),refundVoucherUrl:this.refundUrl,remark:this.refundRemark||'区县代确认线下退款'}).then(()=>this.load())},close(){uni.showModal({title:'关闭退回单',editable:true,placeholderText:'请输入关闭原因',success:r=>{if(r.confirm)closeJkHandledReturn({businessId:this.id,remark:r.content||'区县代关闭'}).then(()=>this.load())}})}}}</script>
<style scoped>.page{min-height:100vh;background:#f3f8f6;padding:24rpx}.card{display:flex;flex-direction:column;gap:14rpx;margin-bottom:18rpx;padding:26rpx;border-radius:20rpx;background:#fff;color:#567168}.row{display:flex;justify-content:space-between}.title{font-weight:650;color:#28594a}.status{color:#18a479}.warn{color:#bd6817}.line{padding:12rpx 0;border-bottom:1rpx solid #edf2f0}.log{padding:12rpx 0;border-bottom:1rpx solid #edf2f0}.muted{display:block;color:#9aaba5;font-size:23rpx}input,textarea{box-sizing:border-box;width:100%;padding:20rpx;border-radius:14rpx;background:#f3f6f5}textarea{height:150rpx}button{margin:0}</style>
